export function chunk(text) {
  const sentences = text.replace(/\\s+/g, ' ').trim().match(/[^.?!…]+[.?!…]+["”']?\\s*|[^.?!…]+$/g).map((x) => x.trim());
  const out = [];
  for (const sentence of sentences) {
    // clauses end in , : ; or precede a dash
    const clauses = sentence.split(/(?<=[,:;])\\s+|\\s+(?=— )/).filter(Boolean);
    let cur = '';
    const flush = () => { if (cur) out.push(cur); cur = ''; };
    for (const clause of clauses) {
      if (!cur && clause.length <= MAX) { cur = clause; continue; }
      if (cur && (cur + ' ' + clause).length <= MAX) { cur = cur + ' ' + clause; continue; }
      if (clause.length <= MAX) { flush(); cur = clause; continue; }
      // a long clause: fill by words, balancing the two halves
      flush();
      const words = clause.split(' ');
      let line = '';
      for (const w of words) {
        if ((line ? line + ' ' + w : w).length > MAX) { out.push(line); line = w; } else line = line ? line + ' ' + w : w;
      }
      cur = line;
    }
    flush();
  }
  // re-balance: a very short chunk joins its neighbour inside the same sentence
  for (let i = 1; i < out.length; i++) {
    if (out[i].length < 10 && !/[.?!…]$/.test(out[i - 1]) && (out[i - 1] + ' ' + out[i]).length <= MAX) {
      out[i - 1] += ' ' + out[i];
      out.splice(i--, 1);
    }
  }
  return out;
}

